import functools
import time
import random

# ========== 1. 基础计时装饰器（演示functools.wraps）==========
def timer(func):
    """计算函数执行时间（毫秒）"""
    @functools.wraps(func)  # 保留原函数的__name__等属性
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        try:
            result = func(*args, **kwargs)
            return result
        finally:
            # 使用finally确保无论是否异常都计算时间
            elapsed = (time.perf_counter() - start) * 1000
            print(f"{func.__name__} 耗时 {elapsed:.2f} ms")
    return wrapper

@timer
def slow_add(a, b):
    """模拟耗时加法"""
    time.sleep(0.1)
    return a + b

print(slow_add(3, 4))          # 运行并打印时间
print("函数名:", slow_add.__name__)  # 输出 slow_add（没有wraps会变成wrapper）

# ========== 2. 带参数的装饰器（可配置重试次数和延迟）==========
def retry(max_attempts=3, delay=0.5):
    """装饰器工厂：失败时重试指定次数"""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    print(f"第 {attempt} 次调用 {func.__name__} 失败: {e}")
                    if attempt < max_attempts:
                        time.sleep(delay)
                    else:
                        raise  # 最后一次重试失败时抛出异常
            return None
        return wrapper
    return decorator

@retry(max_attempts=3, delay=0.2)
def unreliable_divide(a, b):
    """模拟可能因随机数失败的函数"""
    if random.random() < 0.6:  # 60%概率失败
        raise ValueError("随机出错")
    return a / b

# 执行几次验证
for _ in range(2):
    try:
        print("结果:", unreliable_divide(10, 2))
    except Exception:
        print("最终失败")

# ========== 3. 类装饰器（状态保持）==========
class CountCalls:
    """类装饰器：统计函数调用次数"""
    def __init__(self, func):
        functools.update_wrapper(self, func)  # 手动更新元数据
        self.func = func
        self.count = 0

    def __call__(self, *args, **kwargs):
        self.count += 1
        print(f"调用第 {self.count} 次")
        return self.func(*args, **kwargs)

@CountCalls
def say_hello(name):
    return f"Hello, {name}!"

print(say_hello("Alice"))
print(say_hello("Bob"))

