import functools

def my_decorator(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@my_decorator
def greet(name):
    """Greet someone"""
    return f"Hello {name}"

print(greet.__name__)  # 期望打印 'greet'
print(greet.__doc__)   # 期望打印 'Greet someone'

@decorator1
@decorator2
def func():
    pass
# 等价于 func = decorator1(decorator2(func))

def deco_a(func):
    print('A outer')
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print('A before')
        result = func(*args, **kwargs)
        print('A after')
        return result
    return wrapper

def deco_b(func):
    print('B outer')
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print('B before')
        result = func(*args, **kwargs)
        print('B after')
        return result
    return wrapper

@deco_a
@deco_b
def hello():
    print('hello!')

print('--- 调用前 ---')
hello()
